import { test, expect } from '@playwright/test';

test.describe('Table Empty State Illustration', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/your-table-page-url'); // Replace with your actual URL
  });

  test('should display empty state illustration when table has no data', async ({ page }) => {
    // Assuming the table is empty and the illustration has a specific role
    const emptyStateIllustration = page.getByRole('img', { name: /no data illustration/i });
    await expect(emptyStateIllustration).toBeVisible();
  });

  test('should display empty state message when table has no data', async ({ page }) => {
    const emptyStateMessage = page.getByText(/no data available/i);
    await expect(emptyStateMessage).toBeVisible();
  });
});
